#ifndef STDLIB_LAPACK_BASE_DPBEQU_PREFLIGHT_H
#define STDLIB_LAPACK_BASE_DPBEQU_PREFLIGHT_H

#include "stdlib/lapack/base/shared.h"
#include <limits.h>
#include <stddef.h>
#include <stdint.h>
#include <math.h>

typedef char dpbequ_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( uintmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];

/** Indexed element and physical byte envelope. */
typedef struct {
	LAPACK_INT lo;
	LAPACK_INT hi;
	uintptr_t first;
	uintptr_t last;
} dpbequ_envelope;

/** Returns the maximum configured signed LAPACK integer. */
static inline LAPACK_INT dpbequ_max( void ) {
	return (LAPACK_INT)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/** Adds configured integers without overflowing. */
static inline int dpbequ_add( const LAPACK_INT a, const LAPACK_INT b, LAPACK_INT *out ) {
	const LAPACK_INT limit = dpbequ_max();
	const LAPACK_INT minimum = -limit-1;
	if ( ( b > 0 && a > limit-b ) || ( b < 0 && a < minimum-b ) ) return 0;
	*out = a+b;
	return 1;
}

/** Validates a stride and returns the terminal element displacement. */
static inline int dpbequ_step( const LAPACK_INT extent, const LAPACK_INT stride, LAPACK_INT *out ) {
	const LAPACK_INT limit = dpbequ_max();
	LAPACK_INT magnitude;

	// Reject a minimum integer before any negation, including singletons:
	if ( stride == -limit-1 ) return 0;
	if ( extent <= 1 ) {
		*out = 0;
		return 1;
	}
	magnitude = stride < 0 ? -stride : stride;
	if ( magnitude == 0 ) return 0;
	if ( extent-1 > limit/magnitude ) return 0;
	*out = (extent-1)*stride;
	return 1;
}

/** Computes the greatest common divisor of two positive integers. */
static inline LAPACK_INT dpbequ_gcd( LAPACK_INT a, LAPACK_INT b ) {
	LAPACK_INT remainder;
	while ( b != 0 ) {
		remainder = a%b;
		a = b;
		b = remainder;
	}
	return a;
}

/** Checks full-band injectivity after individual strides were validated. */
static inline int dpbequ_injective( const LAPACK_INT rows, const LAPACK_INT columns, const LAPACK_INT stride1, const LAPACK_INT stride2 ) {
	LAPACK_INT a;
	LAPACK_INT b;
	LAPACK_INT divisor;

	if ( rows <= 1 || columns <= 1 ) return 1;
	a = stride1 < 0 ? -stride1 : stride1;
	b = stride2 < 0 ? -stride2 : stride2;
	divisor = dpbequ_gcd( a, b );
	return !( b/divisor < rows && a/divisor < columns );
}

/**
* Checks index and byte endpoints without constructing a derived pointer.
*
* Capacity, alignment and exclusive stable lifetime remain caller duties.
*/
static inline int dpbequ_physical( const double *base, const LAPACK_INT offset, const LAPACK_INT low, const LAPACK_INT high, dpbequ_envelope *out ) {
	const uintmax_t size = sizeof( double );
	uintptr_t address;
	uintmax_t top;
	LAPACK_INT lo;
	LAPACK_INT hi;

	if ( offset < 0 || !dpbequ_add( offset, low, &lo ) || lo < 0 || !dpbequ_add( offset, high, &hi ) || hi < lo ) return 0;
	if ( size-1 > (uintmax_t)PTRDIFF_MAX || (uintmax_t)hi > ( (uintmax_t)PTRDIFF_MAX-(size-1) )/size ) return 0;
	top = (uintmax_t)hi*size+(size-1);
	if ( top > UINTPTR_MAX ) return 0;
	address = (uintptr_t)base;
	if ( address > UINTPTR_MAX-(uintptr_t)top ) return 0;
	out->lo = lo;
	out->hi = hi;
	out->first = address+(uintptr_t)lo*sizeof( double );
	out->last = address+(uintptr_t)top;
	return 1;
}

/** Validates a mutable scalar envelope. */
static inline int dpbequ_scalar( const double *data, const LAPACK_INT offset, dpbequ_envelope *out ) {
	return data != NULL && dpbequ_physical( data, offset, 0, 0, out );
}

/** Tests conservative physical byte overlap. */
static inline int dpbequ_overlaps( const dpbequ_envelope *a, const dpbequ_envelope *b ) {
	return a->first <= b->last && b->first <= a->last;
}

/**
* Computes scales after geometry and all active aliases were validated.
*
* The complete finite diagonal scan precedes every output write. A
* nonpositive failure still copies all diagonals and computes full AMAX;
* SCOND retains its caller sentinel. Returns -1 for a nonfinite diagonal.
*/
static inline LAPACK_INT dpbequ_compute( const int uplo, const LAPACK_INT N, const LAPACK_INT KD, const double *AB, LAPACK_INT strideAB1, LAPACK_INT strideAB2, const LAPACK_INT offsetAB, double *S, LAPACK_INT strideS, const LAPACK_INT offsetS, double *SCOND, const LAPACK_INT offsetSCOND, double *AMAX, const LAPACK_INT offsetAMAX ) {
	LAPACK_INT indexAB;
	LAPACK_INT indexS;
	LAPACK_INT first;
	LAPACK_INT j;
	double smallest;
	double largest;
	double value;

	// Unused singleton strides were validated but need not enter arithmetic:
	if ( KD == 0 ) strideAB1 = 0;
	if ( N == 1 ) {
		strideAB2 = 0;
		strideS = 0;
	}
	indexAB = offsetAB+( uplo == LAPACK_UPPER_TRIANGLE ? KD*strideAB1 : 0 );
	for ( j = 0; j < N; j++ ) {
		if ( !isfinite( AB[ indexAB ] ) ) return -1;
		if ( j+1 < N ) indexAB += strideAB2;
	}
	indexAB = offsetAB+( uplo == LAPACK_UPPER_TRIANGLE ? KD*strideAB1 : 0 );
	indexS = offsetS;
	smallest = AB[ indexAB ];
	largest = smallest;
	first = 0;
	for ( j = 0; j < N; j++ ) {
		value = AB[ indexAB ];
		S[ indexS ] = value;
		if ( value < smallest ) smallest = value;
		if ( value > largest ) largest = value;
		if ( first == 0 && value <= 0.0 ) first = j+1;
		if ( j+1 < N ) {
			indexAB += strideAB2;
			indexS += strideS;
		}
	}
	AMAX[ offsetAMAX ] = largest;
	if ( first != 0 ) return first;
	indexS = offsetS;
	for ( j = 0; j < N; j++ ) {
		S[ indexS ] = 1.0/sqrt( S[ indexS ] );
		if ( j+1 < N ) indexS += strideS;
	}
	SCOND[ offsetSCOND ] = sqrt( smallest )/sqrt( largest );
	return 0;
}

#endif // !STDLIB_LAPACK_BASE_DPBEQU_PREFLIGHT_H
